const assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
function importsFor(file,tracked){const src=fs.readFileSync(file,'utf8'),out=[],re=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi;let m;while((m=re.exec(src))){let v=m[1].replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))v=v.replace(/^\/+/, '');else if(!v.startsWith('assets/'))v=path.posix.normalize(path.posix.join(path.posix.dirname(file),v));if(tracked.has(v))out.push(v)}return out}
function grepEmitters(needle){const r=cp.spawnSync('git',['grep','-l','-F',needle,'--','*.html','assets/js/**/*.js'],{encoding:'utf8'});if(r.status!==0&&r.status!==1)throw new Error(`git grep failed ${r.status}: ${r.stderr}`);return (r.stdout||'').trim().split(/\r?\n/).filter(f=>f&&(f.endsWith('.html')||f.startsWith('assets/js/'))).sort()}
function verifyStatic(){assert(sh('git rev-parse HEAD')===SHA,'wrong HEAD');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'target blob drift');assert(sh(`git hash-object ${IMPORTER}`)===IMPORTER_BLOB,'importer blob drift');assert(sh(`git hash-object ${PAGE}`)===PAGE_BLOB,'page blob drift');assert(sh(`git hash-object ${FEED_RUNTIME}`)===FEED_BLOB,'feed runtime blob drift');assert(sh(`git hash-object ${CARD_RUNTIME}`)===CARD_BLOB,'card runtime blob drift');const html=fs.readFileSync(PAGE,'utf8'),feed=fs.readFileSync(FEED_RUNTIME,'utf8'),card=fs.readFileSync(CARD_RUNTIME,'utf8');assert(html.includes('assets/js/components/public-service-card.js')&&html.includes('assets/js/pages/home/public-services.js'),'home runtime scripts missing');assert(feed.includes('Doke.publicServiceCard.create(item)'),'feed renderer authority drift');assert(card.includes("article.className = 'doke-ad-card doke-ad-card--featured'")&&card.includes("body.className='doke-ad-card__body'")&&card.includes("title.className='doke-ad-card__title'"),'current card renderer authority drift');assert(!feed.includes('service-card__avatar')&&!feed.includes('service-card__tags')&&!card.includes('service-card__avatar')&&!card.includes('service-card__tags'),'legacy anatomy unexpectedly emitted by current runtime');const avatarEmitters=grepEmitters('service-card__avatar'),tagEmitters=grepEmitters('service-card__tags');assert(avatarEmitters.length===0,`avatar runtime emitter returned: ${avatarEmitters.join(',')}`);assert(tagEmitters.length===0,`tags runtime emitter returned: ${tagEmitters.join(',')}`);const report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8')),tracked=new Set(sh('git ls-files -z assets/css').split('\0').filter(f=>f.endsWith('.css'))),direct=[...tracked].filter(f=>importsFor(f,tracked).includes(TARGET)).sort();assert(JSON.stringify(direct)===JSON.stringify([IMPORTER]),`direct importer drift ${JSON.stringify(direct)}`);const reached=[];for(const p of report.pageAssets){const seen=new Set(),todo=[...(p.css||[]).filter(f=>tracked.has(f))];let hit=false;while(todo.length){const f=todo.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break}for(const n of importsFor(f,tracked))todo.push(n)}if(hit)reached.push(p.page)}reached.sort();assert(JSON.stringify(reached)===JSON.stringify([PAGE]),`active reach drift ${JSON.stringify(reached)}`);console.log(`REACH AUTHORITY PASS|page=${PAGE}|directImporter=${IMPORTER}|feedRuntime=${FEED_RUNTIME}|cardRuntime=${CARD_RUNTIME}|target=${TARGET}|affectedFamilies=2`);console.log(`RUNTIME EMITTER PASS|avatarEmitters=${avatarEmitters.length}|tagEmitters=${tagEmitters.length}|currentRenderer=doke-ad-card|fixtureRequired=1`)}
function verifyDead(){const p=parse(fs.readFileSync(TARGET,'utf8'));assert(p.declarations.length===147&&p.dead.length===4,`target parse drift ${p.declarations.length}/${p.dead.length}`);const ds=p.dead;assert(ds.map(d=>d.line).join(',')==='120,121,142,143',`dead line drift ${ds.map(d=>d.line)}`);assert(ds[0].selector===AVATAR_SEL&&ds[0].property==='width'&&ds[0].value==='30px !important'&&ds[0].winnerLine===270&&ds[0].winnerValue==='30px !important'&&ds[0].important&&ds[0].winnerImportant,'dead row 120 drift');assert(ds[1].selector===AVATAR_SEL&&ds[1].property==='height'&&ds[1].value==='30px !important'&&ds[1].winnerLine===271&&ds[1].winnerValue==='30px !important'&&ds[1].important&&ds[1].winnerImportant,'dead row 121 drift');assert(ds[2].selector===TAGS_SEL&&ds[2].property==='overflow'&&ds[2].value==='hidden !important'&&ds[2].winnerLine===341&&ds[2].winnerValue==='hidden !important'&&ds[2].important&&ds[2].winnerImportant,'dead row 142 drift');assert(ds[3].selector===TAGS_SEL&&ds[3].property==='margin'&&ds[3].value==='0 0 14px'&&ds[3].winnerLine===340&&ds[3].winnerValue==='0'&&!ds[3].important&&!ds[3].winnerImportant,'dead row 143 drift');assert(ds.every(d=>d.context.includes('@media (max-width: 560px)')),'context drift');console.log('STATIC CASCADE PASS|decl=147|dead=4|families=2|identical=3|changed=1|context=max560|lines=120,121,142,143|winnerLines=270,271,341,340');return p}
function removeDead(p){const src=fs.readFileSync(TARGET,'utf8'),nl=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(`${d.property}:`),`source line drift ${d.line}`);lines.splice(d.line-1,1)}fs.writeFileSync(TARGET,lines.join('\n')+(nl?'\n':''));const after=parse(fs.readFileSync(TARGET,'utf8')),stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(after.declarations.length===143&&after.dead.length===0,`after parse drift ${after.declarations.length}/${after.dead.length}`);assert(stat[0]==='0'&&stat[1]==='4'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);console.log('R1 REMOVE PASS|decl=147->143|dead=4->0|families=2|additions=0|deletions=4')}
async function prepare(page){await page.waitForFunction(()=>window.Doke?.publicServiceCard?.create,null,{timeout:5000});await page.evaluate(()=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.documentElement.classList.remove('doke-mobile-shell-pending');const section=document.querySelector('.featured-services');if(section)section.hidden=false;const host=document.querySelector('[data-home-list="featured-services"]');if(!host)throw new Error('featured host missing');host.textContent='';const card=window.Doke.publicServiceCard.create({id:'ux052',title:'Serviço de teste',category:'Serviço',providerName:'Profissional Doke',price:120,location:'Belo Horizonte, MG',tags:['teste']});card.dataset.ux052RuntimeCard='true';host.appendChild(card);const freeze=document.createElement('style');freeze.setAttribute('data-ux052-freeze','');freeze.textContent='*,*::before,*::after{transition-duration:0s!important;transition-delay:0s!important;animation-duration:0s!important;animation-delay:0s!important}';document.head.appendChild(freeze)})}
async function snap(page,width){return page.evaluate(({width,AVATAR_SEL,TAGS_SEL})=>{const card=document.querySelector('[data-ux052-runtime-card]'),body=card?.querySelector('.doke-ad-card__body'),title=card?.querySelector('.doke-ad-card__title');if(!card||!body||!title)throw new Error('current runtime card missing');const cb=getComputedStyle(body),ct=getComputedStyle(title),r=card.getBoundingClientRect(),round=n=>Math.round(n*1000)/1000;return{width,legacyAvatarMatches:document.querySelectorAll(AVATAR_SEL).length,legacyTagsMatches:document.querySelectorAll(TAGS_SEL).length,current:{cardClass:card.className,bodyPadding:cb.padding,titleFontSize:ct.fontSize,titleLineHeight:ct.lineHeight,rect:[round(r.x),round(r.y),round(r.width),round(r.height)]},doc:[document.documentElement.clientWidth,document.documentElement.scrollWidth,document.body.scrollWidth]};},{width,AVATAR_SEL,TAGS_SEL})}
async function capture(browser,tag){const out={};let overflow=0;for(const width of VIEWPORTS){const ctx=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),page=await ctx.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url()),local=u.origin==='http://127.0.0.1:4173';if(!local)return route.abort();if(u.pathname.endsWith('.js')&&!u.pathname.endsWith('/assets/js/components/public-service-card.js'))return route.abort();return route.continue()});await page.goto(`http://127.0.0.1:4173/${PAGE}?ux052-r1-${tag}-${width}`,{waitUntil:'domcontentloaded',timeout:20000});await prepare(page);const s=await snap(page,width);assert(s.legacyAvatarMatches===0&&s.legacyTagsMatches===0,`legacy selector unexpectedly present ${width}`);if(s.doc[1]>s.doc[0]+1||s.doc[2]>s.doc[0]+1)overflow++;out[String(width)]=s;await ctx.close()}console.log(`R1 REAL CAPTURE|tag=${tag}|page=${PAGE}|viewports=${VIEWPORTS.join(',')}|samples=${VIEWPORTS.length}|legacyMatches=0|horizontalOverflowSamples=${overflow}`);return{out,overflow}}
(async()=>{assert(SHA&&TARGET_BLOB&&IMPORTER_BLOB&&PAGE_BLOB&&FEED_BLOB&&CARD_BLOB,'missing env');verifyStatic();const parsed=verifyDead();const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(parsed);const after=await capture(browser,'after');assert(before.overflow===after.overflow,`overflow parity drift ${before.overflow}/${after.overflow}`);assert(JSON.stringify(before.out)===JSON.stringify(after.out),'current runtime parity mismatch');console.log(`R1 REAL RUNTIME PASS|page=${PAGE}|renderer=doke-ad-card|viewports=${VIEWPORTS.length}|before=${VIEWPORTS.length}|after=${VIEWPORTS.length}|runtimeDiffs=0|legacyMatches=0|overflowParity=${before.overflow}->${after.overflow}|criticalBoundaries=389/390/391+559/560/561`);console.log('R1 FIXTURE REQUIRED|reason=legacy-families-have-no-html-js-emitter|families=2|next=R2-canonical-fixture')}finally{await browser.close()}}finally{server.kill('SIGTERM')}sh(`git reset --hard ${SHA}`);sh('git clean -fdx');assert(sh('git rev-parse HEAD')===SHA&&sh(`git hash-object ${TARGET}`)===TARGET_BLOB&&sh('git status --porcelain')==='','restore drift');console.log(`R1 CHECKPOINT PASS|sha=${SHA}|productMutation=0|issueCreated=0|prCreated=0`)})().catch(e=>{console.error(e.stack||e);process.exit(1)});
